"""Bounded-bearing geometry. Coordinates m; public angles degrees. Standard library only."""
import itertools
import math

TOL = 1e-7

def add(a,b): return (a[0]+b[0],a[1]+b[1])
def sub(a,b): return (a[0]-b[0],a[1]-b[1])
def mul(a,t): return (a[0]*t,a[1]*t)
def dot(a,b): return a[0]*b[0]+a[1]*b[1]
def cross(a,b): return a[0]*b[1]-a[1]*b[0]
def dist(a,b): return math.hypot(a[0]-b[0],a[1]-b[1])
def unit(deg):
    t=math.radians(deg); return (math.cos(t),math.sin(t))
def bearing(a,b): return math.degrees(math.atan2(b[1]-a[1],b[0]-a[0]))%360

def wedge(s,theta,alpha=1.0):
    if not 0<alpha<90: raise ValueError('Require 0 < alpha < 90 degrees')
    lo,hi=unit(theta-alpha),unit(theta+alpha)
    n1,n2=(lo[1],-lo[0]),(-hi[1],hi[0])
    return [(n1[0],n1[1],dot(n1,s)),(n2[0],n2[1],dot(n2,s))]

def inside(p,hps,tol=TOL): return all(a*p[0]+b*p[1]<=c+tol for a,b,c in hps)

def hull(points):
    pts=sorted(points); unique=[]
    for p in pts:
        if not unique or dist(p,unique[-1])>TOL: unique.append(p)
    if len(unique)<3: return unique
    def half(seq):
        h=[]
        for p in seq:
            while len(h)>1 and cross(sub(h[-1],h[-2]),sub(p,h[-1]))<=1e-10: h.pop()
            h.append(p)
        return h
    return half(unique)[:-1]+half(reversed(unique))[:-1]

def intersection(observations,alpha=1.0):
    """Pure wedges, no artificial clipping box; statuses empty/unbounded/bounded."""
    hs=[h for x,y,t in observations for h in wedge((x,y),t,alpha)]
    if not hs: return {'status':'unbounded','vertices':[],'diameter':None}
    pts=[]
    for (a,b,c),(d,e,f) in itertools.combinations(hs,2):
        det=a*e-b*d
        if abs(det)<1e-12: continue
        p=((c*e-b*f)/det,(a*f-c*d)/det)
        if inside(p,hs): pts.append(p)
    if not pts: return {'status':'empty','vertices':[],'diameter':None}
    vs=hull(pts)
    for a,b,_ in hs:
        for v in [(b,-a),(-b,a)]:
            if all(d*v[0]+e*v[1]<=1e-12 for d,e,_ in hs):
                return {'status':'unbounded','vertices':vs,'diameter':None}
    return dict(status='bounded',vertices=vs,**diameter_info(vs))

def diameter_info(vs):
    if not vs: raise ValueError('Empty polygon')
    a,b=max(itertools.product(vs,repeat=2),key=lambda pair:dist(*pair))
    d=dist(a,b); c=mul(add(a,b),0.5)
    excess=max(dist(v,c)-d/2 for v in vs)
    return {'diameter':d,'diameter_pair':[a,b],'diameter_center':c,
            'diameter_circle_covers':excess<=TOL,'circle_excess':excess}

def enclosing_circle(vs):
    if not vs: raise ValueError('Empty polygon')
    best=(None,math.inf)
    def consider(c,r):
        nonlocal best
        if r<best[1] and all(dist(v,c)<=r+TOL for v in vs): best=(c,r)
    for v in vs: consider(v,0)
    for a,b in itertools.combinations(vs,2):
        c=mul(add(a,b),0.5); consider(c,dist(a,b)/2)
    for a,b,c in itertools.combinations(vs,3):
        ab,ac=sub(b,a),sub(c,a); den=2*cross(ab,ac)
        if abs(den)<1e-12: continue
        bb,cc=dot(ab,ab),dot(ac,ac)
        o=add(a,((bb*ac[1]-cc*ab[1])/den,(ab[0]*cc-ac[0]*bb)/den))
        consider(o,dist(o,a))
    if best[0] is None: raise ArithmeticError('No enclosing circle')
    return best

def clip(poly,hp):
    if not poly:return []
    a,b,c=hp; out=[]
    for p,q in zip(poly,poly[1:]+poly[:1]):
        fp=a*p[0]+b*p[1]-c; fq=a*q[0]+b*q[1]-c
        ip,iq=fp<=TOL,fq<=TOL
        if ip: out.append(p)
        if ip!=iq:
            t=fp/(fp-fq); out.append(add(p,mul(sub(q,p),t)))
    return hull(out)

def clip_wedge(poly,s,theta,alpha=1.0):
    for h in wedge(s,theta,alpha): poly=clip(poly,h)
    return poly

def circle_hps(c,r,n=128):
    return [(u[0],u[1],dot(u,c)+r) for u in (unit(360*j/n) for j in range(n))]

def prior(s,theta,alpha=1.0,n=128):
    # Outer tangent polygon: every real point in both circles remains feasible.
    poly=[(-1800,-1800),(1800,-1800),(1800,1800),(-1800,1800)]
    for h in circle_hps((0,0),1800,n)+circle_hps(s,1500,n)+wedge(s,theta,alpha):
        poly=clip(poly,h)
    return poly

def local_to_global(s,theta,p):
    u=unit(theta);v=(-u[1],u[0]);return add(s,add(mul(u,p[0]),mul(v,p[1])))

def guaranteed(b,alpha=1.0):
    """Continuous guarantee over r in [5,1500], angle in [-alpha,alpha]."""
    ang=math.degrees(math.atan2(b[1],b[0]))
    opposite=(ang+360)%360-180
    ts=[-alpha,alpha]
    if -alpha<=opposite<=alpha: ts.append(opposite)
    minimum=min(dot(b,unit(t)) for t in ts)
    return all(dot(b,b)+r*r-2*r*minimum<=max(1000,r)**2+TOL for r in (5,1000,1500))

def sampled_score(s,theta,b,sources,errors,alpha=1.0,poly=None):
    if poly is None: poly=prior(s,theta,alpha)
    worst=0.0
    for g in sources:
        if dist(b,g)<=5: continue
        t=bearing(b,g)
        for e in errors:
            p=clip_wedge(poly,b,t+e,alpha)
            if not p: raise ArithmeticError('Sample excluded by its own wedge')
            worst=max(worst,diameter_info(p)['diameter'])
    return worst

def source_samples(s,theta,alpha=1.0,dense=False):
    rs=[6]+list(range(50 if dense else 100,1501,50 if dense else 100))
    ts=[-alpha,-alpha/2,0,alpha/2,alpha] if dense else [-alpha,0,alpha]
    return [g for r in rs for t in ts if dist((0,0),g:=local_to_global(s,theta,mul(unit(t),r)))<=1800+TOL]
"""Deterministic coverage and bearing localization. No simulator truth access."""
import math
from geometry import (dist,unit,add,sub,mul,dot,bearing,prior,clip_wedge,
                      diameter_info,enclosing_circle,local_to_global,guaranteed)
from robot_client import RobotError

ALPHA=1.005

def cells(h):
    n=math.ceil(1800/h)
    for i in range(-n,n):
        for j in range(-n,n):
            x,y=i*h,j*h
            nearest=(max(x,min(0,x+h)),max(y,min(0,y+h)))
            if dist(nearest,(0,0))<=1800:
                yield [(x,y),(x+h,y),(x+h,y+h),(x,y+h)]

def scan_nodes(mode):
    h=1200 if mode=='q3' else 600
    pts={(0.,0.)}
    for cell in cells(h):
        if mode=='q3':pts.add(mul(add(cell[0],cell[2]),0.5))
        else:pts.update(cell)
    remaining=pts-{(0.,0.)};ordered=[(0.,0.)]
    while remaining:
        p=min(remaining,key=lambda v:(dist(ordered[-1],v),v))
        ordered.append(p);remaining.remove(p)
    return ordered

def fallback_points(s,theta):
    w=1500*math.sin(math.radians(ALPHA))
    xs=list(range(0,1500,28))+[1500]
    return [local_to_global(s,theta,(x,y)) for y,xx in [(-w/2,xs),(w/2,list(reversed(xs)))] for x in xx]

class BudgetStop(Exception): pass

class Strategy:
    def __init__(self,client,mode='q3'):
        if mode not in ('q3','q4'): raise ValueError('mode must be q3/q4')
        self.client=client;self.mode=mode;self.cleared=set();self.measure_count=0
        self.clear_count=0;self.trace=[];self.fallback_count=0
    def action(self,kind,p,ch):
        left=self.client.time_left()
        if left is not None and left<30: raise BudgetStop('real_time_budget')
        if self.client.virtual_time+dist(self.client.position,p)/5+6>359000:
            raise BudgetStop('virtual_time_budget')
        status,res=getattr(self.client,kind)(p[0],p[1],ch)
        if status!=200 or not isinstance(res,dict) or res.get('accepted') is not True:
            raise RobotError('Rejected action: %s %s'%(status,res))
        self.trace.append(dict(kind=kind,x=p[0],y=p[1],channel=ch,response=res,
                               virtual_time_s=self.client.virtual_time))
        if kind=='measure': self.measure_count+=1
        else:
            self.clear_count+=1
            if res.get('clear_result')=='success':self.cleared.add(ch)
        return res
    def locate(self,s,ch,res):
        if res['measure_result']=='near':
            r=self.action('clear',s,ch)
            if r['clear_result']!='success':raise RobotError('near then clear failed')
            return
        theta=res['svd_deg'];poly=prior(s,theta,ALPHA);last=s;last_theta=theta
        for _ in range(4):
            if not poly: raise RobotError('Inconsistent bearing polygon')
            c,r=enclosing_circle(poly)
            if r<=19.9:
                out=self.action('clear',c,ch)
                if out['clear_result']!='success':raise RobotError('Certified clear failed')
                return
            d=diameter_info(poly)['diameter'];u=unit(last_theta);v=(-u[1],u[0])
            offset=max(40,min(300,0.2*d))
            candidates=[add(c,mul(v,offset)),add(c,mul(v,-offset))]
            u0=unit(theta);v0=(-u0[1],u0[0])
            candidates.sort(key=lambda p:(not guaranteed((dot(sub(p,s),u0),dot(sub(p,s),v0)),ALPHA),dist(last,p),p))
            p=candidates[0];out=self.action('measure',p,ch)
            if out['measure_result']=='near':
                hit=self.action('clear',p,ch)
                if hit['clear_result']!='success':raise RobotError('near clear failed')
                return
            if out['measure_result']=='no_signal':break
            poly=clip_wedge(poly,p,out['svd_deg'],ALPHA);last=p;last_theta=out['svd_deg']
        self.fallback_count+=1
        for p in fallback_points(s,theta):
            if self.action('clear',p,ch)['clear_result']=='success':return
        raise RobotError('Complete strip sweep failed: model/interface inconsistent')
    def run(self):
        status='complete_coverage'
        try:
            for p in scan_nodes(self.mode):
                chs=[c for c in range(1,21) if c not in self.cleared]
                chs.sort(key=lambda c:(c!=self.client.channel,c))
                for ch in chs:
                    res=self.action('measure',p,ch)
                    if res['measure_result'] in ('direction','near'):self.locate(p,ch,res)
                    if len(self.cleared)==16:
                        status='complete_upper_bound';return self.summary(status)
        except BudgetStop as exc: status=str(exc)
        return self.summary(status)
    def summary(self,status):
        n=len(self.cleared)
        return dict(mode=self.mode,status=status,cleared=n,channels=sorted(self.cleared),
                    virtual_time_s=self.client.virtual_time,
                    average_time_s=self.client.virtual_time/n if n else None,
                    measures=self.measure_count,clear_attempts=self.clear_count,
                    fallback_count=self.fallback_count,official_validated=False)
"""In-process synthetic fixture. Separate from official simulator; no HTTP fidelity claim."""
import math,random,time
from geometry import dist,bearing,unit,dot,sub

class OfflineClient:
    def __init__(self,mode,seed,count=12):
        rng=random.Random(seed);self.sources=[];self.err={};self.rng=random.Random(seed+777)
        for ch in rng.sample(range(1,21),count):
            r=math.sqrt(rng.random())*1800;t=rng.uniform(0,360);u=unit(t)
            self.sources.append(dict(channel=ch,x=r*u[0],y=r*u[1],radius=rng.uniform(1000,1500),
                                     direction=rng.uniform(0,360) if mode=='q4' and rng.random()<0.5 else None,cleared=False))
        self.position=(0.,0.);self.channel=1;self.virtual_time=0.;self.started=time.monotonic()
    def time_left(self): return 1200-(time.monotonic()-self.started)
    def source(self,c):return next((s for s in self.sources if s['channel']==c and not s['cleared']),None)
    def move(self,x,y):
        self.virtual_time+=dist(self.position,(x,y))/5;self.position=(x,y)
    def measure(self,x,y,c):
        self.move(x,y);self.virtual_time+=5+(c!=self.channel);self.channel=c;s=self.source(c)
        result='no_signal';angle=None
        if s:
            g=(s['x'],s['y']);r=dist(g,(x,y))
            visible=s['direction'] is None or dot(sub((x,y),g),unit(s['direction']))>=0
            if r<=s['radius'] and visible:
                result='near' if r<=5 else 'direction'
                if result=='direction':
                    key=(c,round(x,6),round(y,6))
                    if key not in self.err:self.err[key]=self.rng.uniform(-1,1)
                    angle=round((bearing((x,y),g)+self.err[key])%360,2)%360
        res=dict(accepted=True,virtual_time_s=self.virtual_time,measure_result=result)
        if angle is not None:res['svd_deg']=angle
        return 200,res
    def clear(self,x,y,c):
        self.move(x,y);s=self.source(c);hit=s is not None and dist((x,y),(s['x'],s['y']))<=20
        if hit:s['cleared']=True
        self.virtual_time+=5 if hit else 3
        return 200,dict(accepted=True,virtual_time_s=self.virtual_time,clear_result='success' if hit else 'no_target_in_range')
